function LeadForm({ lead, onClose }: { lead?: Entity; onClose: () => void }) {
  const { state, actor, execute, busy } = useApp();
  const [error, setError] = useState('');
  return <WorkflowDialog title={lead ? 'Editar oportunidade' : 'Nova oportunidade'} onClose={onClose}><form onSubmit={async event => { const form = formValues(event); try { await execute({ type: 'save', collection: 'leads', ...(lead ? { id: lead.id } : {}), data: { nome: inputText(form, 'nome'), empresa: inputText(form, 'empresa'), telefone: inputText(form, 'telefone'), email: inputText(form, 'email'), origem: inputText(form, 'origem'), canal: inputText(form, 'canal'), responsavelId: inputText(form, 'responsavelId'), valorEstimado: inputNumber(form, 'valorEstimado'), etapa: text(lead?.etapa) || 'Lead', observacoes: inputText(form, 'observacoes'), cnpj: inputText(form, 'cnpj'), atividade: inputText(form, 'atividade'), cidade: inputText(form, 'cidade'), uf: inputText(form, 'uf').toUpperCase(), empresaAtiva: inputText(form, 'empresaAtiva'), principalProblema: inputText(form, 'principalProblema'), motivoBusca: inputText(form, 'motivoBusca'), decisor: inputText(form, 'decisor'), urgencia: inputText(form, 'urgencia'), classificacao: inputText(form, 'classificacao') } }); onClose(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Não foi possível salvar a oportunidade.'); } }}><div className="wf-grid"><FormField label="Nome do contato"><input name="nome" required defaultValue={text(lead?.nome)} autoComplete="name"/></FormField><FormField label="Empresa"><input name="empresa" required defaultValue={text(lead?.empresa)} autoComplete="organization"/></FormField><FormField label="Telefone com DDI" help="Exemplo de formato: +5562999999999"><input name="telefone" required type="tel" defaultValue={text(lead?.telefone)} autoComplete="tel"/></FormField><FormField label="E-mail"><input name="email" type="email" defaultValue={text(lead?.email)}/></FormField><FormField label="CNPJ"><input name="cnpj" defaultValue={text(lead?.cnpj)}/></FormField><FormField label="Atividade principal" help="O que a empresa faz, na linguagem do cliente."><input name="atividade" defaultValue={text(lead?.atividade)}/></FormField><FormField label="Cidade"><input name="cidade" defaultValue={text(lead?.cidade)}/></FormField><FormField label="UF" help="Sigla com duas letras."><input name="uf" maxLength={2} defaultValue={text(lead?.uf)} style={{ textTransform: 'uppercase' }}/></FormField><FormField label="Origem" help="De onde a pessoa veio."><select name="origem" required defaultValue={text(lead?.origem)}><option value="">Como chegou ao escritório?</option>{origins.map(item => <option key={item}>{item}</option>)}</select></FormField><FormField label="Canal" help="Por onde a pessoa falou. Só o WhatsApp é integrado."><select name="canal" defaultValue={text(lead?.canal)}><option value="">Não informado</option>{channels.map(item => <option key={item}>{item}</option>)}</select></FormField><FormField label="Empresa está ativa?"><select name="empresaAtiva" defaultValue={text(lead?.empresaAtiva)}><option value="">Não informado</option><option>Sim</option><option>Em abertura</option><option>Não</option></select></FormField><FormField label="Participação na decisão" help="A pessoa decide ou consegue trazer quem decide?"><input name="decisor" defaultValue={text(lead?.decisor)} placeholder="Quem decide a contratação"/></FormField><FormField label="Urgência ou prazo"><input name="urgencia" defaultValue={text(lead?.urgencia)} placeholder="Existe data limite?"/></FormField><FormField label="Classificação" help="Escolha manual. Os critérios ficam ao lado como lembrete."><select name="classificacao" defaultValue={text(lead?.classificacao)}><option value="">Ainda não classificado</option>{classifications.map(item => <option key={item}>{item}</option>)}</select></FormField><FormField label="Responsável"><TeamSelect team={state.equipe} value={text(lead?.responsavelId) || actor.memberId || actor.id}/></FormField><FormField label="Valor mensal estimado (R$)" help="Deixe zero enquanto não houver estimativa."><input name="valorEstimado" type="number" min="0" step="0.01" defaultValue={text(lead?.valorEstimado) || '0'}/></FormField><FormField label="Principal problema hoje" full><textarea name="principalProblema" defaultValue={text(lead?.principalProblema)} placeholder="A dor que o cliente descreveu, com as palavras dele."/></FormField><FormField label="Motivo da busca" full><textarea name="motivoBusca" defaultValue={text(lead?.motivoBusca)} placeholder="Por que está procurando outro contador agora."/></FormField><FormField label="Contexto da oportunidade" full><textarea name="observacoes" defaultValue={text(lead?.observacoes)} placeholder="Próximos passos e o que mais foi combinado."/></FormField></div><div className="wf-note" style={{ marginTop: 18 }}><strong>Seis perguntas mínimas antes de agendar.</strong><ul style={{ margin: '8px 0 0', paddingLeft: 18 }}>{PERGUNTAS_MINIMAS_AGENDAMENTO.map(item => <li key={item.campo}>{item.rotulo}</li>)}</ul><p style={{ marginBottom: 0, marginTop: 8 }}>Resposta desconhecida vira "não informado" e não impede o agendamento.</p></div><FieldError error={error}/><FormActions busy={busy} label={lead ? 'Salvar alterações' : 'Cadastrar oportunidade'} onClose={onClose}/></form></WorkflowDialog>;
}

